package net.civeira.phylax.feature.identity.userfederatedidentity.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.feature.identity.userfederatedidentity.application.visibility.UserFederatedIdentityVisibilityCheck;

public class TenantAccessible {

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes UserFederatedIdentityVisibilityCheck filter) {
    Actor actor = filter.getActor();
    if (!(actor.hasScope("platform:global_access"))) {
      filter.peek(fl -> fl.setUserTenantAccessible(actor.getTenant()));
    }
  }
}
